package com.ruoyi.warehouse.data;

import com.ruoyi.common.utils.SecurityUtils;
import com.ruoyi.warehouse.catalog.WarehouseCatalog;
import com.ruoyi.warehouse.security.*;
import com.ruoyi.warehouse.support.*;
import java.time.Instant;
import java.util.*;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.*;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class MasterImportService {
    private final WarehouseRepository records;private final MasterDataService master;private final WarehouseCatalog catalog;private final WarehouseScope scope;private final WarehouseFields fields;private final TransactionTemplate tx;private final JdbcTemplate jdbc;
    private static final Set<String> KINDS=Set.of("clients","products","warehouses","locations","locationTypes","suppliers","channels");
    public MasterImportService(WarehouseRepository records,MasterDataService master,WarehouseCatalog catalog,WarehouseScope scope,WarehouseFields fields,PlatformTransactionManager manager){this.records=records;this.master=master;this.catalog=catalog;this.scope=scope;this.fields=fields;jdbc=records.jdbc();tx=new TransactionTemplate(manager);tx.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);}
    private void permission(String kind,String action){if(!KINDS.contains(kind))throw WarehouseException.invalid("This master data type is not available / 此类主数据尚未开放");if(!scope.admin()&&!SecurityUtils.hasPermi("warehouse:"+kind+":"+action))throw WarehouseException.forbidden();}
    private void writePermission(String kind,String mode){if(Set.of("suppliers","channels").contains(kind))scope.requireAdministrator();permission(kind,"import");permission(kind,"create".equals(mode)?"add":"edit");if(!"create".equals(mode))permission(kind,"query");}
    public Map<String,Object> preview(String kind,String mode,String name,byte[] bytes){
        if(!Set.of("create","update").contains(mode))throw WarehouseException.invalid("Choose create or update / 请选择新增或更新");writePermission(kind,mode);if(name==null||name.length()>191||name.indexOf('\0')>=0)throw WarehouseException.invalid("Invalid filename");
        var table=MasterWorkbook.read(name,bytes,fields.transferFields(kind,true));
        var rehearsal=tx.execute(status->{try{return run(kind,mode,table.rows(),true,status);}finally{status.setRollbackOnly();}});
        if(!WarehouseJson.maps(rehearsal.get("errors")).isEmpty())return project(kind,Map.of("valid",false,"kind",kind,"mode",mode,"fileName",name,"rows",rehearsal.get("rows"),"errors",rehearsal.get("errors")));
        return tx.execute(status->{writePermission(kind,mode);if(jdbc.queryForObject("SELECT COUNT(*) FROM wh_master_import WHERE actor_id=? AND status='PREVIEW'",Long.class,scope.actor())>=100)throw WarehouseException.conflict("Cancel unused previews before uploading more / 请先撤销不用的预检记录");
            String id=UUID.randomUUID().toString();var document=new LinkedHashMap<String,Object>();document.put("id",id);document.put("_version",1);document.put("actor",scope.actor());document.put("kind",kind);document.put("mode",mode);document.put("status","PREVIEW");document.put("valid",true);document.put("fileName",name);document.put("fileHash",MasterImportInput.hash(Base64.getEncoder().encodeToString(bytes)));document.put("createdAt",Instant.now().toString());document.put("inputs",rehearsal.get("inputs"));document.put("rows",rehearsal.get("rows"));document.put("errors",List.of());document.put("planHash",MasterImportInput.hash(rehearsal.get("rows")));
            String json=WarehouseJson.write(document);if(json.length()>6000000)throw WarehouseException.invalid("Preview exceeds capacity; use a smaller batch / 预检资料过大，请减少每批行数");
            jdbc.update("INSERT INTO wh_master_import(id,kind,actor_id,revision,status,document_json,document_hash) VALUES(?,?,?,1,'PREVIEW',?,?)",id,kind,scope.actor(),json,MasterImportInput.hash(document));records.audit("PREVIEW_MASTER_IMPORT",kind,id,null,Map.of("fileHash",document.get("fileHash"),"count",table.rows().size(),"mode",mode));return project(kind,document);
        });
    }
    private Map<String,Object> run(String kind,String mode,List<Map<String,Object>> input,boolean dry,TransactionStatus status){
        var previews=new ArrayList<Map<String,Object>>();var errors=new ArrayList<Map<String,Object>>();var resolved=new ArrayList<Map<String,Object>>();var results=new ArrayList<Map<String,Object>>();var targets=new HashSet<String>();
        for(var row:input){Object savepoint=dry?status.createSavepoint():null;try{
            var data=WarehouseJson.map(WarehouseJson.write(row.get("data")));String id=WarehouseJson.text(data,"id");data.remove("id");if("create".equals(mode)){if(!id.isEmpty()||data.containsKey("_version"))throw WarehouseException.invalid("Create rows cannot specify id or version / 新增不能携带编号或版本");id=null;}else if(id.isEmpty()||!targets.add(id))throw WarehouseException.invalid("Update requires a unique id for each row / 更新必须有编号且一条记录只能出现一次");
            var before=id==null?Map.<String,Object>of():records.scoped(kind,id,true);fields.writable(kind,data);resolveReferences(kind,data);
            var saved=master.saveInTransaction(kind,id,data);var dependencies=new ArrayList<Map<String,Object>>();for(var ref:jdbc.queryForList("SELECT r.kind,r.id FROM wh_reference x JOIN wh_record r ON r.id=x.target_id WHERE x.owner_id=? ORDER BY r.id FOR UPDATE",saved.get("id")))dependencies.add(records.scoped(String.valueOf(ref.get("kind")),String.valueOf(ref.get("id")),true));
            var business=new LinkedHashMap<>(saved);for(String key:List.of("id","_version","createdAt","updatedAt"))business.remove(key);
            previews.add(Map.of("row",row.get("row"),"before",before,"after",business,"dependencies",dependencies));var normalized=new LinkedHashMap<>(data);if(id!=null)normalized.put("id",id);resolved.add(Map.of("row",row.get("row"),"data",normalized));results.add(Map.of("row",row.get("row"),"id",saved.get("id"),"_version",saved.get("_version")));
        }catch(WarehouseException|DataIntegrityViolationException e){if(!dry)throw WarehouseException.conflict("Row "+row.get("row")+": "+message(e)+" / 整批未写入");status.rollbackToSavepoint(savepoint);errors.add(Map.of("row",row.get("row"),"message",message(e)));}finally{if(dry)status.releaseSavepoint(savepoint);}}
        return Map.of("rows",previews,"errors",errors,"inputs",resolved,"results",results);
    }
    private static String message(RuntimeException e){return e instanceof WarehouseException?e.getMessage():"Duplicate identity or business reference conflict / 编号、SKU、条码或业务关联发生冲突";}
    private void resolveReferences(String kind,Map<String,Object> data){for(var f:catalog.fields(kind)){String key=WarehouseJson.text(f,"key"),source=WarehouseJson.text(f,"source"),value=WarehouseJson.text(data,key);if(!"ref".equals(f.get("type"))||value.isEmpty())continue;
        var direct=jdbc.queryForList("SELECT id FROM wh_record WHERE kind=? AND id=?",String.class,source,value);if(!direct.isEmpty()){records.scoped(source,value,true);continue;}
        var args=new ArrayList<Object>();args.add(source);String where=scope.predicate(source,args);args.add(value);var ids=jdbc.queryForList("SELECT r.id FROM wh_record r WHERE r.kind=? AND "+where+" AND r.display_name=? ORDER BY r.id FOR UPDATE",String.class,args.toArray());
        if(ids.size()!=1)throw WarehouseException.invalid(key+": reference is missing or ambiguous; use a visible unique name or ID / 关联资料不存在或不唯一，请填写有权限的唯一名称或编号");records.scoped(source,ids.get(0),true);data.put(key,ids.get(0));
    }}
    public Map<String,Object> get(String kind,String id){return tx.execute(status->{permission(kind,"import");var row=read(kind,id,false);access(kind,row);return project(kind,row);});}
    public Map<String,Object> list(String kind){return tx.execute(status->{permission(kind,"import");var rows=new ArrayList<Map<String,Object>>();for(String id:jdbc.queryForList("SELECT id FROM wh_master_import WHERE actor_id=? AND kind=? ORDER BY created_at DESC,id LIMIT 100",String.class,scope.actor(),kind))rows.add(summary(read(kind,id,false)));return Map.of("rows",rows);});}
    public Map<String,Object> action(String kind,String id,Map<String,Object> input){return tx.execute(status->{
        permission(kind,"import");MasterImportInput.keys(input,"requestId","_version","action");String action=MasterImportInput.option(input,"action","","commit","cancel"),request=MasterImportInput.id(input,"requestId");var visible=read(kind,id,false);if(((Number)visible.get("actor")).longValue()!=scope.actor())throw WarehouseException.forbidden();if("commit".equals(action)){access(kind,visible);writePermission(kind,WarehouseJson.text(visible,"mode"));for(var row:WarehouseJson.maps(visible.get("inputs")))fields.writable(kind,WarehouseJson.map(WarehouseJson.write(row.get("data"))));}
        String digest=MasterImportInput.hash(Map.of("kind",kind,"id",id,"input",input));jdbc.update("INSERT INTO wh_operation_request(actor_id,request_id,operation_type,request_hash,response_json) VALUES(?,?, 'MASTER_IMPORT',?, '{}') ON DUPLICATE KEY UPDATE request_id=request_id",scope.actor(),request,digest);var replay=jdbc.queryForMap("SELECT operation_type,request_hash,response_json FROM wh_operation_request WHERE actor_id=? AND request_id=? FOR UPDATE",scope.actor(),request);if(!"MASTER_IMPORT".equals(replay.get("operation_type"))||!digest.equals(replay.get("request_hash")))throw WarehouseException.conflict("Request identity already used / 请求编号已用于其他内容");if(!"{}".equals(replay.get("response_json")))return "cancel".equals(action)?summary(read(kind,id,true)):project(kind,read(kind,id,true));
        var before=read(kind,id,true);if(!"PREVIEW".equals(before.get("status"))||((Number)before.get("_version")).longValue()!=WarehouseJson.integer(input.get("_version"),"_version",1,Long.MAX_VALUE))throw WarehouseException.conflict("Import preview changed / 预检记录已变化");var data=WarehouseJson.copy(before);
        if("commit".equals(action)){for(var row:WarehouseJson.maps(before.get("inputs")))fields.writable(kind,WarehouseJson.map(WarehouseJson.write(row.get("data"))));var result=run(kind,WarehouseJson.text(before,"mode"),WarehouseJson.maps(before.get("inputs")),false,status);if(!before.get("planHash").equals(MasterImportInput.hash(result.get("rows"))))throw WarehouseException.conflict("Data or references changed since preview; upload and preview again / 资料或关联配置已变化，请重新预检；整批未写入");data.put("results",result.get("results"));data.put("status","COMMITTED");}else data.put("status","CANCELLED");
        data.put("_version",((Number)before.get("_version")).longValue()+1);data.put("completedAt",Instant.now().toString());jdbc.update("UPDATE wh_master_import SET revision=?,status=?,document_json=?,document_hash=? WHERE id=?",data.get("_version"),data.get("status"),WarehouseJson.write(data),MasterImportInput.hash(data),id);records.audit("COMMIT_MASTER_IMPORT".equals(action)?action:"MASTER_IMPORT_"+action.toUpperCase(Locale.ROOT),kind,id,summary(before),summary(data));jdbc.update("UPDATE wh_operation_request SET response_json=? WHERE actor_id=? AND request_id=?",WarehouseJson.write(Map.of("id",id,"status",data.get("status"))),scope.actor(),request);return "cancel".equals(action)?summary(data):project(kind,data);
    });}
    private Map<String,Object> read(String kind,String id,boolean lock){var rows=jdbc.query("SELECT * FROM wh_master_import WHERE kind=? AND id=?"+(lock?" FOR UPDATE":""),(rs,n)->{var data=WarehouseJson.map(rs.getString("document_json"));if(!MasterImportInput.hash(data).equals(rs.getString("document_hash"))||!id.equals(data.get("id"))||!kind.equals(data.get("kind"))||rs.getLong("actor_id")!=((Number)data.get("actor")).longValue()||rs.getLong("revision")!=((Number)data.get("_version")).longValue()||!rs.getString("status").equals(data.get("status")))throw WarehouseException.conflict("Import evidence mismatch / 导入证据校验失败");return data;},kind,id);if(rows.size()!=1)throw WarehouseException.missing();return rows.get(0);}
    private void access(String kind,Map<String,Object> document){if(((Number)document.get("actor")).longValue()!=scope.actor())throw WarehouseException.forbidden();for(var row:WarehouseJson.maps(document.get("rows"))){var after=WarehouseJson.map(WarehouseJson.write(row.get("after")));var before=WarehouseJson.map(WarehouseJson.write(row.get("before")));if(before.containsKey("id")){after.put("id",before.get("id"));records.scoped(kind,String.valueOf(before.get("id")),false);}scope.assertRecord(kind,after);for(var ref:WarehouseJson.maps(row.get("dependencies"))){String refId=WarehouseJson.text(ref,"id");var kinds=jdbc.queryForList("SELECT kind FROM wh_record WHERE id=?",String.class,refId);if(kinds.size()!=1)throw WarehouseException.conflict("Import reference is no longer available / 关联资料已不存在");records.scoped(kinds.get(0),refId,false);}}for(var result:WarehouseJson.maps(document.get("results")))records.scoped(kind,WarehouseJson.text(result,"id"),false);}
    private Map<String,Object> project(String kind,Map<String,Object> document){var result=summary(document);var rows=new ArrayList<Map<String,Object>>();var allowed=new HashSet<String>();for(var field:fields.transferFields(kind,false))allowed.add(WarehouseJson.text(field,"key"));allowed.addAll(List.of("id","_version"));for(var row:WarehouseJson.maps(document.get("rows"))){var before=fields.readable(kind,WarehouseJson.map(WarehouseJson.write(row.get("before"))));var after=fields.readable(kind,WarehouseJson.map(WarehouseJson.write(row.get("after"))));decimalText(kind,before);decimalText(kind,after);before.keySet().retainAll(allowed);after.keySet().retainAll(allowed);var changed=new ArrayList<String>();for(String key:after.keySet())if(!Objects.equals(before.get(key),after.get(key)))changed.add(key);rows.add(Map.of("row",row.get("row"),"before",before,"after",after,"changed",changed));}result.put("rows",rows);result.put("errors",document.getOrDefault("errors",List.of()));if(document.containsKey("results"))result.put("results",document.get("results"));return result;}
    private void decimalText(String kind,Map<String,Object> row){for(var field:catalog.fields(kind)){String key=WarehouseJson.text(field,"key");Object value=row.get(key);if("number".equals(field.get("type"))&&value instanceof Number)row.put(key,value instanceof java.math.BigDecimal number?number.toPlainString():value.toString());}}
    private static Map<String,Object> summary(Map<String,Object> document){var result=new LinkedHashMap<String,Object>();for(String key:List.of("id","_version","kind","mode","status","valid","fileName","fileHash","createdAt","completedAt"))if(document.containsKey(key))result.put(key,document.get(key));result.put("count",WarehouseJson.maps(document.get("rows")).size());return result;}
    public byte[] workbook(String kind,boolean template,String mode,int page,int size,String keyword){
        permission(kind,template?"import":"export");if(template&&!Set.of("create","update").contains(mode))throw WarehouseException.invalid("Invalid template mode");if(!template){permission(kind,"list");permission(kind,"query");}if(page<1||size<1||size>500)throw WarehouseException.invalid("Export page size must be 1–500 / 每份导出为 1 至 500 行");
        return tx.execute(status->{var rows=new ArrayList<Map<String,Object>>();long total=0;if(!template){long start=(long)(page-1)*size;for(long offset=start;offset<start+size;){int sourcePage=(int)(offset/200)+1;var data=records.list(kind,sourcePage,200,keyword);total=((Number)data.get("total")).longValue();var chunk=WarehouseJson.maps(data.get("rows"));int skip=(int)(offset%200);if(skip>=chunk.size())break;for(int i=skip;i<chunk.size()&&offset<start+size;i++,offset++)rows.add(fields.readable(kind,chunk.get(i)));if(offset>=total)break;}}
            var metadata=new LinkedHashMap<String,Object>();metadata.put("Type / 类型",kind);metadata.put("Mode / 模式",template?mode:"update");metadata.put("Rows / 本文件行数",rows.size());metadata.put("Filtered total / 筛选总数",total);metadata.put("Page / 批次",page);metadata.put("Rules / 规则","First sheet only; max 500 rows / 只读取首张表，每批最多 500 行。Empty cells keep defaults/current values; __CLEAR__ clears a field; prefix \\ to keep this literal / 空白保留默认或原值，__CLEAR__ 清空，前加反斜杠保留原文。");metadata.put("References / 关联","Use existing record ID or a unique name within your scope / 填写已有资料编号或权限范围内唯一名称。Codes and dates must be text / 编码和日期请用文本。Update keeps id and _version / 更新保留编号及版本。");
            return MasterWorkbook.write(fields.transferFields(kind,template),rows,!template||"update".equals(mode),metadata);
        });
    }
}
